/**
 * Regenerates `@deutsch-mate/api-schemas` from `docs/openapi.yaml`.
 * Generated files under `src/generated/` must never be hand-edited.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const openapiPath = path.join(repoRoot, "docs/openapi.yaml");
const generatedPath = path.join(repoRoot, "packages/api-schemas/src/generated/openapi.ts");

const ast = await openapiTS(new URL(`file://${openapiPath}`), {
  rootTypes: true,
  rootTypesNoSchemaPrefix: true,
  exportType: true,
});
const contents = astToString(ast);

const banner = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

fs.mkdirSync(path.dirname(generatedPath), { recursive: true });
fs.writeFileSync(generatedPath, `${banner}${contents}`, "utf8");

const written = fs.readFileSync(generatedPath, "utf8");
if (!written.includes("auto-generated by openapi-typescript")) {
  console.error("generated file is missing the openapi-typescript banner");
  process.exit(1);
}
if (!written.includes("export type paths") || !written.includes("export type UuidV7")) {
  console.error("generated file is missing required OpenAPI type exports");
  process.exit(1);
}

console.log(`openapi:generate wrote ${path.relative(repoRoot, generatedPath)}`);
